import type { Plan } from "./types";

export interface SoundCue { sceneId: string; event: "reveal" | "interaction-result" | "legacy-reveal"; startFrame: number; durationFrames: number; gainDb: number }

/** Reuses one licensed generated effect. No new audio calls or inferred beat detection. */
export function soundCues(plan: Plan): SoundCue[] {
  if (!plan.creativeDirection) return plan.scenes[1] ? [{ sceneId: plan.scenes[1].id, event: "legacy-reveal", startFrame: plan.scenes[1].start_frame, durationFrames: 36, gainDb: -12 }] : [];
  const candidates: SoundCue[] = [];
  const reveal = plan.scenes.find(scene => !scene.preserve_audio && scene.direction?.motion === "reveal" && scene.direction.job === "context")
    ?? plan.scenes.find(scene => !scene.preserve_audio && scene.direction?.motion === "reveal");
  if (reveal) candidates.push({ sceneId: reveal.id, event: "reveal", startFrame: reveal.start_frame + Math.min(12, reveal.duration_frames - 1), durationFrames: 30, gainDb: -15 });
  for (const scene of plan.scenes) {
    const visual = scene.presentation?.visual;
    if (scene.preserve_audio || !scene.direction || visual?.kind !== "ui-demo") continue;
    const result = visual.actions.filter(action => action.kind === "state" || action.kind === "select").at(-1);
    if (result) candidates.push({ sceneId: scene.id, event: "interaction-result", startFrame: scene.start_frame + result.atFrame + result.durationFrames, durationFrames: 24, gainDb: -19 });
  }
  const accepted: SoundCue[] = [];
  for (const cue of candidates.sort((a, b) => a.startFrame - b.startFrame)) {
    const scene = plan.scenes.find(scene => scene.id === cue.sceneId)!;
    cue.durationFrames = Math.min(cue.durationFrames, scene.start_frame + scene.duration_frames - cue.startFrame, plan.output.duration_frames - cue.startFrame);
    if (cue.durationFrames < 6 || !Number.isInteger(cue.startFrame) || cue.startFrame < 0 || accepted.some(previous => cue.startFrame - previous.startFrame < 90)) continue;
    if (plan.scenes.some(speech => speech.preserve_audio && cue.startFrame < speech.start_frame + speech.duration_frames && cue.startFrame + cue.durationFrames > speech.start_frame)) continue;
    accepted.push(cue);
    if (accepted.length === 3) break;
  }
  return accepted;
}

/** Recompile timing after allowed scene-duration repairs; asset identity stays fixed. */
export function alignAudioToPlan(plan: Plan, audio: Plan["audio"]): Plan["audio"] {
  if (!plan.creativeDirection) return audio.map(layer => ({ ...layer, start_frame: layer.role === "sfx" ? plan.scenes[1].start_frame : 0, duration_frames: layer.role === "music" ? plan.output.duration_frames : layer.duration_frames }));
  const music = audio.filter(layer => layer.role === "music").map(layer => ({ ...layer, start_frame: 0, duration_frames: plan.output.duration_frames }));
  // A quiet repair can remove all scheduled cues without discarding the one
  // generated effect. Later repairs reuse that saved asset without another call.
  const retainedEffect=plan.assets.find(asset=>asset.id==="generated-sfx"&&asset.kind==="audio"&&asset.usage==="output"&&asset.has_audio);
  const effect = audio.find(layer => layer.role === "sfx") ?? (retainedEffect?{asset_id:retainedEffect.id,start_frame:0,duration_frames:36,source_in_seconds:0,playback_rate:1 as const,gain_db:-12,role:"sfx" as const}:undefined);
  if (!effect) return music;
  return [...music, ...soundCues(plan).map(cue => ({ ...effect, start_frame: cue.startFrame, duration_frames: cue.durationFrames, source_in_seconds: 0, gain_db: cue.gainDb }))];
}

export function soundCueIssues(plan: Plan): string[] {
  if (!plan.creativeDirection || !plan.audio.length) return [];
  const expected = soundCues(plan), actual = plan.audio.filter(layer => layer.role === "sfx");
  if (actual.length !== expected.length || actual.some((layer, i) => layer.start_frame !== expected[i].startFrame || layer.duration_frames !== expected[i].durationFrames || layer.gain_db !== expected[i].gainDb || layer.source_in_seconds !== 0 || layer.asset_id !== actual[0].asset_id)) return ["Directed sound cues do not match their compiled reveal/action events"];
  return [];
}

export const soundDirectionReport = (plan: Plan) => ({ version: 1, mode: plan.creativeDirection ? "directed-events" : "legacy-reveal", cues: soundCues(plan), generatedEffectCount: new Set(plan.audio.filter(layer => layer.role === "sfx").map(layer => layer.asset_id)).size, humanListeningPerformed: false, beatDetectionPerformed: false });

import { PipelineError, type AudioFailure } from "./types";

// Only explicit documented rejection codes permit another POST. HTTP 429 alone
// is not enough to classify a historical or malformed response safely.
// https://elevenlabs.io/docs/eleven-api/resources/errors
// https://elevenlabs.io/docs/help-center/technical/api-error-code-429
export const MAX_AUDIO_ATTEMPTS = 3;
export const MAX_AUDIO_ERROR_BYTES = 16_384;
const RATE_CODES = new Set(["rate_limit_exceeded", "concurrent_limit_exceeded", "too_many_concurrent_requests", "system_busy"]);
const ACCESS_CODES = new Set(["invalid_api_key", "missing_api_key", "unauthorized", "forbidden", "insufficient_permissions", "workspace_access_denied", "feature_not_available", "subscription_required", "model_access_denied"]);
const token = (value: unknown, max: number): string | null => typeof value === "string" && value.length <= max && /^[A-Za-z0-9_.:-]+$/.test(value) ? value : null;

export function classifyAudioFailure(httpStatus: number, code: string | null, type: string | null): AudioFailure["classification"] {
  if (httpStatus === 402 || code === "insufficient_credits" || code === "quota_exceeded") return "quota";
  if (httpStatus === 401 || httpStatus === 403 || (code !== null && ACCESS_CODES.has(code))) return "access";
  if (httpStatus === 429 && code !== null && RATE_CODES.has(code) && (type === null || type === "rate_limit_error")) return "rate_limit";
  return "unknown";
}

/** RFC 9110: seconds or HTTP-date. Invalid values never become a zero delay. */
export function retryAfterMs(value: string | null, now: number): number | null {
  if (!value) return null;
  const text = value.trim();
  if (/^\d+$/.test(text)) {
    const delay = Number(text) * 1000;
    // A valid but enormous delay must stop this job, never fall back to seconds.
    return Number.isSafeInteger(delay) && delay >= 0 && Number.isSafeInteger(now + delay) ? delay : Number.MAX_SAFE_INTEGER - now;
  }
  if (text.length > 128) return null;
  // Avoid Date.parse accepting unrelated strings such as "-1" or "1.5".
  if (!/^(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun), \d{2} (?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \d{4} \d{2}:\d{2}:\d{2} GMT$/.test(text)) return null;
  const date = Date.parse(text);
  return Number.isSafeInteger(date) ? Math.max(0, date - now) : null;
}

async function errorJson(response: Response): Promise<unknown> {
  if (!response.body || Number(response.headers.get("content-length")) > MAX_AUDIO_ERROR_BYTES) { await response.body?.cancel(); throw new Error("Invalid error body"); }
  const reader = response.body.getReader(), chunks: Uint8Array[] = [];
  let size = 0;
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      size += value.byteLength;
      if (size > MAX_AUDIO_ERROR_BYTES) { await reader.cancel(); throw new Error("Oversized error body"); }
      chunks.push(value);
    }
  } finally { reader.releaseLock(); }
  return JSON.parse(Buffer.concat(chunks).toString("utf8"));
}

/** Retain identifiers, never provider messages, source prompts, keys or exception text. */
export async function audioFailure(response: Response, attempt: number, receivedAt: number): Promise<AudioFailure> {
  let code: string | null = null, type: string | null = null, bodyRequestId: string | null = null;
  try {
    const body = await errorJson(response);
    const detail = body && typeof body === "object" && "detail" in body ? body.detail : undefined;
    if (detail && typeof detail === "object" && !Array.isArray(detail)) {
      // A supplied modern code is authoritative, even if malformed/unknown.
      code = token("code" in detail ? detail.code : "status" in detail ? detail.status : undefined, 128);
      type = token("type" in detail ? detail.type : undefined, 128);
      bodyRequestId = token("request_id" in detail ? detail.request_id : undefined, 512);
      if ("type" in detail && type === null) code = null;
    }
  } catch { /* An unreadable error cannot authorize a retry. */ }
  return {
    attempt, httpStatus: response.status, code, type,
    requestId: token(response.headers.get("request-id"), 512) || token(response.headers.get("x-request-id"), 512) || bodyRequestId,
    classification: classifyAudioFailure(response.status, code, type), receivedAt,
    retryAfterMs: retryAfterMs(response.headers.get("retry-after"), receivedAt),
  };
}

export function nextAudioAttemptAt(failure: AudioFailure, random = Math.random()): number {
  const backoff = 5000 * 2 ** (failure.attempt - 1) + Math.floor(Math.max(0, Math.min(1, random)) * 1000);
  return failure.receivedAt + Math.max(backoff, failure.retryAfterMs ?? 0);
}

export function audioFailureError(classification: AudioFailure["classification"], waitingForDeadline = false): PipelineError {
  if (classification === "rate_limit") return new PipelineError("audio_rate_limited", waitingForDeadline ? "The audio provider's retry delay exceeds this job's remaining processing time." : "The audio provider remained rate-limited after bounded retries.", "Your plan and completed audio were retained. Ask the administrator to review provider capacity before recovering this job.", "needs_review");
  if (classification === "quota") return new PipelineError("audio_quota_exceeded", "The audio provider rejected the request because its credit allowance is exhausted.", "Ask the administrator to check the audio account's credits and spending limits. The retained plan and completed audio do not need regeneration.", "needs_review");
  if (classification === "access") return new PipelineError("audio_access_denied", "The audio provider denied access to this generation request.", "Ask the administrator to check the API key, subscription, and music/sound-effect permissions. The retained plan and completed audio do not need regeneration.", "needs_review");
  return uncertainAudioError();
}

export function uncertainAudioError(): PipelineError {
  return new PipelineError("audio_payment_uncertain", "An audio request has an unresolved outcome or checkpoint.", "Ask the administrator to inspect the retained request and recover any provider output before retrying. Automatic repeated generation was prevented; a reservation does not prove billing.", "needs_review");
}

import type { Page } from "playwright";
import { join } from "node:path";
import { probe, writeJson } from "./media";
import type { Asset, BrandEvidence } from "./types";

export interface LogoCandidate {
  selector: string; url?: string; label: string; clues: string;
  width: number; height: number; visible: boolean; inNavigation: boolean; linksHome: boolean;
}
export function rankLogoCandidates(candidates: LogoCandidate[]) {
  const seen = new Set<string>();
  return candidates.slice(0, 80).filter(candidate => {
    if (!candidate.visible || candidate.width < 12 || candidate.height < 12 || candidate.width > 800 || candidate.height > 800 || candidate.width * candidate.height < 200) return false;
    if (!/(?:logo|wordmark|brand)/i.test(candidate.clues)) return false;
    if (!candidate.inNavigation && !candidate.linksHome) return false;
    const key = candidate.url || candidate.selector;
    if (seen.has(key)) return false;
    seen.add(key); return true;
  }).sort((a, b) => Number(b.linksHome) * 3 + Number(b.inNavigation) - Number(a.linksHome) * 3 - Number(a.inNavigation)).slice(0, 4);
}

/** Observed public styles and original DOM logo pixels, never a guessed official brand kit. */
export async function extractBrandEvidence(page: Page, workspace: string, sourceUrl: string): Promise<{ brand: BrandEvidence; assets: Asset[]; artifactPaths: string[] }> {
  // A string keeps this browser-only DOM collector independent of TS transpiler helpers.
  const observed = await page.evaluate<{
    language: string; title: string; description: string; headings: string[]; callsToAction: string[];
    colors: BrandEvidence["colors"]; typography: BrandEvidence["typography"]; logos: LogoCandidate[];
  }>(`(() => {
    const selector = node => {
      const parts=[]; let item=node;
      while(item && item!==document.documentElement && parts.length<15){
        if(item.id){parts.unshift('#'+CSS.escape(item.id));break;}
        const tag=item.tagName.toLowerCase(), siblings=item.parentElement?Array.from(item.parentElement.children).filter(s=>s.tagName===item.tagName):[];
        parts.unshift(siblings.length>1?tag+':nth-of-type('+(siblings.indexOf(item)+1)+')':tag);item=item.parentElement;
      }
      return parts.join(' > ').slice(0,1200);
    };
    const visible = node => {const b=node.getBoundingClientRect(),s=getComputedStyle(node);return b.width>0&&b.height>0&&s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity)!==0;};
    const clean = (s,n) => String(s||'').replace(/\\s+/g,' ').trim().slice(0,n);
    const headings=Array.from(document.querySelectorAll('h1,h2')).filter(visible).map(n=>clean(n.innerText,120)).filter(Boolean).slice(0,8);
    const actions=Array.from(document.querySelectorAll('a,button')).filter(visible).filter(n=>n.tagName==='BUTTON'||/button|cta|primary/i.test(n.className)||/^(get|start|try|download|learn|explore)\\b/i.test(n.innerText.trim())).slice(0,8);
    const chroma=value=>{const channels=value.match(/[\\d.]+/g)?.slice(0,3).map(Number)||[];return channels.length===3?Math.max(...channels)-Math.min(...channels):0;};
    const styledActions=[...actions].sort((a,b)=>{const sa=getComputedStyle(a),sb=getComputedStyle(b);return Math.max(chroma(sb.color),chroma(sb.backgroundColor))-Math.max(chroma(sa.color),chroma(sa.backgroundColor));});
    const colors=[],typography=[],rootBackground=getComputedStyle(document.documentElement).backgroundColor;
    if(rootBackground!=='rgba(0, 0, 0, 0)'&&rootBackground!=='transparent')colors.push({value:rootBackground,role:'background',selector:'html'});
    const samples=[{node:document.body,role:'body'},{node:document.querySelector('h1'),role:'heading'},...styledActions.slice(0,2).map(node=>({node,role:'label'}))];
    for(const sample of samples){if(!sample.node||!visible(sample.node))continue;const s=getComputedStyle(sample.node),path=selector(sample.node);typography.push({family:clean(s.fontFamily.split(',').slice(0,5).join(','),160),weight:clean(s.fontWeight,30),role:sample.role,selector:path});
      for(const item of [{value:s.color,role:sample.role==='label'?'accent':'text'},{value:s.backgroundColor,role:sample.role==='label'?'accent':'background'}])if(item.value!=='rgba(0, 0, 0, 0)'&&item.value!=='transparent'&&!colors.some(c=>c.value===item.value&&c.role===item.role))colors.push({...item,selector:path});}
    const logos=Array.from(document.querySelectorAll('img,svg')).slice(0,200).map(node=>{const b=node.getBoundingClientRect(),parent=node.parentElement,anchor=node.closest('a'),url=node instanceof HTMLImageElement?(node.currentSrc||node.src):undefined;let linksHome=false;try{const u=new URL(anchor?.href||'',location.href);linksHome=!!anchor&&u.origin===location.origin&&u.pathname.replace(/\\/+$/,'')===location.pathname.replace(/\\/+$/,'');}catch{}
      return{selector:selector(node),url,label:clean(node.getAttribute('alt')||node.getAttribute('aria-label')||node.querySelector('title')?.textContent,160),clues:clean([node.id,node.getAttribute('class'),node.getAttribute('alt'),node.getAttribute('aria-label'),parent?.id,parent?.getAttribute('class'),url].join(' '),600),width:b.width,height:b.height,visible:visible(node)&&(!(node instanceof HTMLImageElement)||(node.complete&&node.naturalWidth>0)),inNavigation:!!node.closest('header,nav,[role=banner]'),linksHome};}).filter(n=>/logo|wordmark|brand/i.test(n.clues)).slice(0,80);
    return{language:clean(document.documentElement.lang,35),title:clean(document.title,200),description:clean(document.querySelector('meta[name=description]')?.content,400),headings,callsToAction:actions.map(n=>clean(n.innerText,100)).filter(Boolean),colors:colors.slice(0,8),typography:typography.slice(0,4),logos};
  })()`);
  const brand: BrandEvidence = { version: 1, sourceUrl, language: observed.language || undefined, title: observed.title,
    description: observed.description || undefined, headings: observed.headings, callsToAction: [...new Set(observed.callsToAction)],
    colors: observed.colors, typography: observed.typography, logoAssetIds: [],
    limitations: ["Colors, typography and language are observed on the public page; they are not a verified official brand manual.", "Logo captures preserve the original public element and its displayed background; no logo was recreated."] };
  const assets: Asset[] = [], artifactPaths: string[] = [], attempts: { selector: string; status: string; reason?: string }[] = [];
  for (const candidate of rankLogoCandidates(observed.logos)) {
    if (assets.length >= 2) break;
    try {
      const id = `brand-logo-${assets.length}`, path = `assets/${id}.png`;
      await page.locator(candidate.selector).screenshot({ path: join(workspace, path), type: "png", timeout: 2500 });
      const media = await probe(join(workspace, path));
      if (!media.video || media.width < 12 || media.height < 12 || media.width > 800 || media.height > 800) throw new Error("Logo element dimensions changed or are unusable");
      assets.push({ id, path, preview: path, kind: "image", usage: "output", width: media.width, height: media.height,
        rights: "Original visible logo element from the submitted public product page; not a product screenshot or invented mark.", source: sourceUrl,
        provenance: { pageUrl: sourceUrl, pageKind: "homepage", method: "element", role: "brand-logo", selector: candidate.selector, assetUrl: candidate.url } });
      brand.logoAssetIds.push(id); artifactPaths.push(path); attempts.push({ selector: candidate.selector, status: "captured" });
    } catch (error) { attempts.push({ selector: candidate.selector, status: "failed", reason: error instanceof Error ? error.message.slice(0,250) : "Logo unavailable" }); }
  }
  if (!assets.length) brand.limitations.push("No confident visible public logo element could be captured.");
  const path = "analysis/brand-evidence.json";
  await writeJson(join(workspace, path), { ...brand, logoCaptureAttempts: attempts }); artifactPaths.push(path);
  return { brand, assets, artifactPaths };
}

import { readFile } from "node:fs/promises";
import { join } from "node:path";
import { z } from "zod";
import { writeJson } from "./media";
import { stageDigest, stageFailure, type Research } from "./research";
import { PipelineError, type Evidence, type Hooks, type Plan, type Presentation } from "./types";
import { uiDocumentSchema, validateUiActions, validateUiDocuments, type UiDocument } from "./ui-reconstruction";
import { uiActionBehaviorIssues } from "./script-ui-behavior";

const factId = z.string().regex(/^fact-\d+$/);
const digest = z.string().regex(/^[a-f0-9]{64}$/);
const claim = z.object({ text: z.string().min(1).max(160), basis: z.enum(["explicit", "inferred"]), evidenceIds: z.array(factId).min(1).max(3) }).strict();
export const creativeConceptSchema = z.enum(["focus", "connect", "consolidate"]);
export const shotJobSchema = z.enum(["hook", "context", "action", "result", "payoff", "cta"]);
export const shotMotionSchema = z.enum(["reveal", "focus", "connect", "consolidate", "hold"]);
export const directionSelectionSchema = z.object({ concept: creativeConceptSchema, evidenceId: factId }).strict();
export const shotSelectionSchema = z.object({ job: shotJobSchema, motion: shotMotionSchema }).strict();
export const shotDirectionSchema = shotSelectionSchema.extend({ version: z.literal(1), continuityKey: z.string().min(1).max(300).optional() }).strict();
const brandSchema = z.object({ sourceUrl: z.string(), colors: z.array(z.object({ value: z.string(), role: z.enum(["accent", "background", "text"]) }).strict()), logoAssetIds: z.array(z.string()) }).strict();
const workflowSchema = z.array(z.object({ action: z.string().min(1).max(80), evidenceId: factId, assetId: z.string().min(1) }).strict()).min(1).max(3);
const conceptOptionSchema = z.object({ concept: creativeConceptSchema, evidenceIds: z.array(factId).min(1).max(24), meaning: z.string().max(350) }).strict();
export const creativeBriefSchema = z.object({
  version: z.literal(1), product: z.string().min(1).max(48), researchSha256: digest, evidenceSha256: digest,
  audience: claim, mechanism: claim, outcome: claim, cta: claim, workflow: workflowSchema,
  brand: brandSchema.nullable(), concepts: z.array(conceptOptionSchema).min(1).max(3),
}).strict();
export const creativeDirectionSchema = creativeBriefSchema.omit({ concepts: true }).extend({
  briefSha256: digest, concept: creativeConceptSchema, evidenceId: factId, evidence: z.string().min(1).max(900),
}).strict();
export type CreativeBrief = z.infer<typeof creativeBriefSchema>;
export type CreativeDirection = z.infer<typeof creativeDirectionSchema>;
export type ShotDirection = z.infer<typeof shotDirectionSchema>;
export type ShotSelection = z.infer<typeof shotSelectionSchema>;
export const CREATIVE_BRIEF_PATH = "analysis/creative-brief.json";
const invalid = (message: string) => new PipelineError("invalid_generated_script", message, "Inspect the retained creative brief and script. Keep the same supported product story and source bindings.", "needs_review");

/** Deterministic, source-bound options for the existing script call; never a new paid stage. */
export function buildCreativeBrief(research: Research, evidence: Evidence): CreativeBrief {
  const story = research.story;
  if (!story?.primaryAudience || !story.mechanism || !story.outcome || !story.cta) throw stageFailure("A creative brief requires the verified audience, workflow, outcome and CTA.");
  const selected = new Map(research.facts.map(fact => [fact.evidenceId, fact]));
  const mechanisms = [...new Set([...story.mechanism.evidenceIds, ...story.mechanism.steps.map(step => step.evidenceId)])];
  if (mechanisms.some(id => !selected.has(id))) throw stageFailure("The creative brief has an unselected workflow fact.");
  const concepts: CreativeBrief["concepts"] = [{ concept: "focus", evidenceIds: mechanisms, meaning: "Establish this actual product, focus attention on its documented action, then return to the complete readable result. The chosen input/control remains the same object." }];
  const relationship = research.facts.filter(fact => /\b(link(?:s|ed|ing)?|connect(?:s|ed|ing|ion|ions)?|relationship(?:s)?|graph|network)\b/i.test(fact.quote)).map(fact => fact.evidenceId);
  if (relationship.length && research.facts.length >= 2) concepts.push({ concept: "connect", evidenceIds: relationship, meaning: "Draw a relationship between two or three individually source-bound informational nodes. This is an explanatory diagram, not an invented application state or decorative network." });
  const grouping = research.facts.filter(fact => /\b(organiz(?:e|es|ed|ing|ation)|organis(?:e|es|ed|ing|ation)|centraliz(?:e|ed|es)|unif(?:y|ied)|collect(?:s|ed|ion|ing)?|consolidat(?:e|es|ed|ion)|one place|all.in.one)\b/i.test(fact.quote)).map(fact => fact.evidenceId);
  const stills = research.visuals.filter(visual => visual.showsProductUi && visual.role === "product_ui" && evidence.assets.some(asset => asset.id === visual.assetId && asset.kind === "image" && asset.usage === "output"));
  const groupingProof = grouping.filter(id => stills.some(visual => visual.supportsFactIds.includes(id)));
  if (groupingProof.length && stills.length >= 2) concepts.push({ concept: "consolidate", evidenceIds: groupingProof, meaning: "Bring two distinct intact, verified product panels into a shared composition. Their original data stays separate; convergence does not imply an undocumented merge or workflow." });
  const { steps: workflow, ...mechanism } = story.mechanism;
  const source = evidence.brand;
  return creativeBriefSchema.parse({ version: 1, product: research.product, researchSha256: stageDigest(research), evidenceSha256: research.evidenceSha256, audience: story.primaryAudience, mechanism, outcome: story.outcome, cta: story.cta, workflow,
    brand: source ? { sourceUrl: source.sourceUrl, colors: source.colors.map(({ value, role }) => ({ value, role })), logoAssetIds: source.logoAssetIds.filter(id => evidence.assets.some(asset => asset.id === id && asset.usage === "output" && asset.provenance?.role === "brand-logo")) } : null, concepts });
}

/** A saved deterministic brief is immutable; persistence must finish before script spending. */
export async function persistCreativeBrief(brief: CreativeBrief, workspace: string, hooks: Pick<Hooks, "persist">) {
  let saved: unknown;
  try { saved = JSON.parse(await readFile(join(workspace, CREATIVE_BRIEF_PATH), "utf8")); }
  catch (error) { if (!(error instanceof Error && "code" in error && error.code === "ENOENT")) throw stageFailure("The retained creative brief is unreadable."); }
  if (saved !== undefined && stageDigest(saved) !== stageDigest(brief)) throw stageFailure("The retained creative brief belongs to changed source evidence or direction policy.");
  if (saved === undefined) await writeJson(join(workspace, CREATIVE_BRIEF_PATH), brief);
  await hooks.persist([CREATIVE_BRIEF_PATH]);
}

export function compileCreativeDirection(selection: unknown, research: Research, evidence: Evidence): CreativeDirection {
  const parsed = directionSelectionSchema.safeParse(selection);
  if (!parsed.success) throw invalid("Choose exactly one supported creative concept and its eligible source fact.");
  const brief = buildCreativeBrief(research, evidence), { concept, evidenceId } = parsed.data;
  if (!brief.concepts.some(option => option.concept === concept && option.evidenceIds.includes(evidenceId))) throw invalid("The selected creative concept is not eligible for its product evidence and available visual primitives.");
  const { concepts: _concepts, ...bound } = brief;
  return creativeDirectionSchema.parse({ ...bound, briefSha256: stageDigest(brief), concept, evidenceId, evidence: research.facts.find(fact => fact.evidenceId === evidenceId)!.quote });
}

interface DirectedScene { storyRole?: string; assetId: string; evidenceId: string; preserveAudio: boolean; presentation?: Presentation; direction?: ShotSelection | ShotDirection }
const roleJobs: Record<string, ShotDirection["job"][]> = { problem: ["hook"], product: ["context"], mechanism: ["action", "result"], outcome: ["result", "payoff"], differentiator: ["payoff"], cta: ["cta"] };
/** Derived identity is a visual motif only. It never carries or fabricates product UI state. */
export function compileShotDirection(scene: DirectedScene): ShotDirection {
  const raw = shotSelectionSchema.safeParse(scene.direction && { job: scene.direction.job, motion: scene.direction.motion });
  if (!raw.success || !roleJobs[scene.storyRole || ""]?.includes(raw.data.job)) throw invalid("Every directed shot needs a job matching its grounded narrative role.");
  const { job, motion } = raw.data, visual = scene.presentation?.visual;
  if (scene.preserveAudio && motion !== "hold") throw invalid("Preserved source speech requires a stable directed shot with motion hold.");
