  const specialV6=value.startsWith("2001:")&&parseInt(value.split(":")[1]||"0",16)<0x200;
  return isIP(value) === 6 && /^[23]/.test(value) && !specialV6 && !value.startsWith("2001:db8") && !value.startsWith("2002:") && !value.startsWith("3fff:");
