      if (!before || !after || before.id === after.id || !elements.has(result.confirmationElementId) || !before.visibleElementIds.includes(result.confirmationElementId) || !unique(result.resultElementIds) || !unique(result.evidenceIds) || result.resultElementIds.some(id => !elements.has(id) || !after.visibleElementIds.includes(id)) || result.evidenceIds.some(id => !document.capabilityFactIds.includes(id) || !after.evidenceIds.includes(id))) throw stageFailure("The terminal result declaration changed its documented states, visible controls, result elements or capability evidence.");
    }
